import{_ as o,r as t,o as l,c as i,e as a,a as p,s as d}from"./chunks/framework.CXcwiNg-.js";const y=JSON.parse('{"title":"Media Finder Field - October CMS - 4.x","titleTemplate":false,"description":"Form Widget","frontmatter":{"subtitle":"Form Widget","shortname":"Media Finder"},"headers":[{"level":2,"title":"Selecting Multiple Items","slug":"selecting-multiple-items","link":"#selecting-multiple-items","children":[{"level":3,"title":"Copying and Pasting Items","slug":"copying-and-pasting-items","link":"#copying-and-pasting-items","children":[]}]}],"relativePath":"4.x/element/form/widget-mediafinder.md","filePath":"4.x/element/form/widget-mediafinder.md"}'),r={name:"4.x/element/form/widget-mediafinder.md"};function c(m,e,u,g,h,k){const s=t("pre-heading"),n=t("post-heading");return l(),i("div",null,[a(s),e[0]||(e[0]=p("h1",null,"Media Finder Field",-1)),a(n),e[1]||(e[1]=d(`<p><code>mediafinder</code> - renders a field for selecting an item from the media manager library. Expanding the field displays the media manager to locate a file. The resulting selection is a string as the relative path to the file.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">whitepaper_file</span><span class="token punctuation">:</span>
    <span class="token key atrule">label</span><span class="token punctuation">:</span> Whitepaper PDF
    <span class="token key atrule">type</span><span class="token punctuation">:</span> mediafinder
</code></pre></div><p>The following <a href="./../form-fields.html">field properties</a> are supported and commonly used.</p><div class="table"><table tabindex="0"><thead><tr><th>Property</th><th>Description</th></tr></thead><tbody><tr><td><strong>label</strong></td><td>a name when displaying the form field to the user.</td></tr><tr><td><strong>default</strong></td><td>specifies a default string value, optional.</td></tr><tr><td><strong>comment</strong></td><td>places a descriptive comment below the field.</td></tr><tr><td><strong>mode</strong></td><td>the expected file type, either <code>file</code>, <code>folder</code> or <code>image</code>. Default: <code>file</code>.</td></tr><tr><td><strong>imageWidth</strong></td><td>if using image type, the preview image will be displayed to this width, optional.</td></tr><tr><td><strong>imageHeight</strong></td><td>if using image type, the preview image will be displayed to this height, optional.</td></tr><tr><td><strong>maxItems</strong></td><td>maximum number of items that can be selected.</td></tr><tr><td><strong>thumbOptions</strong></td><td>additional <a href="./../../extend/services/resizer.html">resize options</a> for generating the thumbnail, or pass <code>false</code> to disable thumb generation.</td></tr><tr><td><strong>useCopyPaste</strong></td><td>shows the select all, copy and paste toolbar buttons when selecting multiple items. Default: <code>false</code>.</td></tr></tbody></table></div><p>Set the <code>mode</code> to <strong>image</strong> to display a preview of the selected image.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">background_image</span><span class="token punctuation">:</span>
    <span class="token key atrule">label</span><span class="token punctuation">:</span> Background Image
    <span class="token key atrule">type</span><span class="token punctuation">:</span> mediafinder
    <span class="token key atrule">mode</span><span class="token punctuation">:</span> image
</code></pre></div><p>You may set the <code>mode</code> to <strong>folder</strong> to only allow selecting a media folder path.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">media_folder</span><span class="token punctuation">:</span>
    <span class="token key atrule">label</span><span class="token punctuation">:</span> Media Folder
    <span class="token key atrule">type</span><span class="token punctuation">:</span> mediafinder
    <span class="token key atrule">mode</span><span class="token punctuation">:</span> folder
</code></pre></div><div class="custom-block tip"><p>Unlike the <a href="./widget-fileupload.html">File Upload form widget</a>, the Media Finder form widget stores its data as a string representing the path to the media files selected within the Media Library. It should associate to a normal attribute on your model.</p></div><h2 id="selecting-multiple-items"><a href="#selecting-multiple-items" class="header-anchor">#</a> Selecting Multiple Items</h2><p>The media finder will attempt to guess if multiple items can be selected based on the <a href="./../../extend/system/models.html">jsonable attribute</a> in the model, which is a requirement for storing multiple items.</p><p>You may limit the number of items that can be selected using the <code>maxItems</code> property.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">media_gallery</span><span class="token punctuation">:</span>
    <span class="token key atrule">label</span><span class="token punctuation">:</span> Image
    <span class="token key atrule">type</span><span class="token punctuation">:</span> mediafinder
    <span class="token key atrule">mode</span><span class="token punctuation">:</span> image
    <span class="token key atrule">maxItems</span><span class="token punctuation">:</span> <span class="token number">10</span>
</code></pre></div><h3 id="copying-and-pasting-items"><a href="#copying-and-pasting-items" class="header-anchor">#</a> Copying and Pasting Items</h3><p>When selecting multiple items, enable the <code>useCopyPaste</code> property to add <strong>Select All</strong>, <strong>Copy Selected</strong> and <strong>Paste</strong> buttons to the toolbar. This lets the user copy a selection from one media finder field and paste it into another.</p><div class="language-yaml extra-class"><pre class="language-yaml"><code><span class="token key atrule">media_gallery</span><span class="token punctuation">:</span>
    <span class="token key atrule">label</span><span class="token punctuation">:</span> Image
    <span class="token key atrule">type</span><span class="token punctuation">:</span> mediafinder
    <span class="token key atrule">mode</span><span class="token punctuation">:</span> image
    <span class="token key atrule">maxItems</span><span class="token punctuation">:</span> <span class="token number">10</span>
    <span class="token key atrule">useCopyPaste</span><span class="token punctuation">:</span> <span class="token boolean important">true</span>
</code></pre></div><p>The copied items are held in the browser and can be pasted into any media finder field that also has this property enabled. Items already present in the target field are skipped, and the <code>maxItems</code> limit is respected when pasting.</p>`,17))])}const b=o(r,[["render",c]]);export{y as __pageData,b as default};
